#include <iostream>
int main() {
    int a[] = {2, 4, 6}, b[] = {1, 3, 5};
    int i = 0, j = 0;
    while (i < 3 && j < 3)
        std::cout << (a[i] < b[j] ? a[i++] : b[j++]);
    while (i < 3) std::cout << a[i++];
    while (j < 3) std::cout << b[j++];
    std::cout << "\n";
    return 0;
}

