#include <iostream>
int main() {
    int a[] = {1, 3, 5};
    int b[] = {2, 4};
    int i = 0, j = 0;
    while (i < 3 && j < 2)
        if (a[i] < b[j]) std::cout << a[i++];
        else std::cout << b[j++];
    while (j < 2) std::cout << b[j++];
    return 0;
}

#include <iostream>
int main() {
    int a[] = {4, 1, 3, 5, 2};
    int pivot = a[4], i = 0;
    for (int j = 0; j < 4; j++)
        if (a[j] < pivot) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; }
    int t = a[i]; a[i] = a[4]; a[4] = t;
    std::cout << i << "\n";
    return 0;
}

