#include <iostream>
int calls = 0;
void rec(int n) {
    calls++;
    if (n <= 1) return;
    rec(n / 2); rec(n - n / 2);
}
int main() {
    rec(8);
    std::cout << calls << "\n";
    return 0;
}

#include <iostream>
int main() {
    int a[] = {7, 2, 9, 4, 3};
    int pivot = a[0], i = 1, j = 4;
    while (i <= j) {
        while (i <= j && a[i] < pivot) i++;
        while (i <= j && a[j] > pivot) j--;
        if (i <= j) { int t = a[i]; a[i] = a[j]; a[j] = t; i++; j--; }
    }
    std::cout << j << "\n";
    return 0;
}
